import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import "../styles/articles.css";

function ArticlesPage() {
  const { category } = useParams();
  const navigate = useNavigate();
  const token = localStorage.getItem("token");

  const [articles, setArticles] = useState([]);
  const [isAdmin, setIsAdmin] = useState(false);
  const [expandedArticles, setExpandedArticles] = useState({}); // { articleId: true/false }
  const [comments, setComments] = useState({}); // { articleId: [comments] }
  const [newComments, setNewComments] = useState({}); // { articleId: "текст" }

  // --- Отримати користувача ---
  useEffect(() => {
    if (!token) return;
    fetch("http://127.0.0.1:8000/api/user/", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => res.json())
      .then((data) => setIsAdmin(data.is_staff || data.is_superuser))
      .catch(console.error);
  }, [token]);

  // --- Завантажити статті ---
  useEffect(() => {
    fetch(`http://127.0.0.1:8000/api/articles/?category=${category}`, {
      headers: {
        "Content-Type": "application/json",
        ...(token && { Authorization: `Bearer ${token}` }),
      },
    })
      .then((res) => res.json())
      .then((data) => setArticles(data))
      .catch(console.error);
  }, [category, token]);

  // --- Завантажити коментарі ---
  const fetchComments = (articleId) => {
    fetch(`http://127.0.0.1:8000/api/comments/?article=${articleId}`)
      .then((res) => res.json())
      .then((data) => setComments((prev) => ({ ...prev, [articleId]: data })))
      .catch(console.error);
  };

  const toggleComments = (articleId) => {
    setExpandedArticles((prev) => {
      const isOpen = prev[articleId];
      if (!isOpen) fetchComments(articleId); // завантажити тільки якщо відкриваємо
      return { ...prev, [articleId]: !isOpen };
    });
  };

  const handleAddComment = (articleId) => {
    const content = newComments[articleId];
    if (!content || !content.trim()) return;

    fetch("http://127.0.0.1:8000/api/comments/", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ article: articleId, content }),
    })
      .then((res) => {
        if (res.ok) {
          setNewComments((prev) => ({ ...prev, [articleId]: "" }));
          fetchComments(articleId);
        }
      })
      .catch(console.error);
  };

  const handleDelete = (id) => {
    if (!window.confirm("Видалити статтю?")) return;

    fetch(`http://127.0.0.1:8000/api/articles/${id}/`, {
      method: "DELETE",
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => {
        if (res.ok) setArticles((prev) => prev.filter((a) => a.id !== id));
      })
      .catch(console.error);
  };

  return (
    <div className="articles-container">
      <h2>{category.toUpperCase()}</h2>
      {articles.length === 0 ? (
        <p>Немає статей у цій категорії.</p>
      ) : (
        <div className="articles-grid">
          {articles.map((a) => (
            <div key={a.id} className="article-card">
              {a.image && <img src={a.image} alt={a.title} className="article-image" />}
              <h3>{a.title}</h3>
              <p>{a.excerpt || (a.content?.substring(0, 120) + "...")}</p>
              <small>{a.category} | {new Date(a.created_at).toLocaleDateString()}</small>

              {isAdmin && (
                <div className="admin-controls">
                  <button onClick={() => navigate(`/edit-article/${a.id}`)}>✏️ Редагувати</button>
                  <button onClick={() => handleDelete(a.id)}>🗑️ Видалити</button>
                </div>
              )}

              <button onClick={() => toggleComments(a.id)}>
                💬 {expandedArticles[a.id] ? "Сховати коментарі" : "Показати коментарі"}
              </button>

              {expandedArticles[a.id] && (
                <div className="comments-section">
                  {comments[a.id] ? (
                    comments[a.id].length > 0 ? (
                      comments[a.id].map((c) => (
                        <div key={c.id} className="comment">
                          <strong>{c.user_username || "Користувач"}</strong>: {c.content}
                        </div>
                      ))
                    ) : (
                      <p>Немає коментарів.</p>
                    )
                  ) : (
                    <p>Завантаження...</p>
                  )}

                  {token && (
                    <div className="add-comment">
                      <textarea
                        value={newComments[a.id] || ""}
                        onChange={(e) =>
                          setNewComments((prev) => ({ ...prev, [a.id]: e.target.value }))
                        }
                        placeholder="Напишіть коментар..."
                      />
                      <button onClick={() => handleAddComment(a.id)}>Надіслати</button>
                    </div>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default ArticlesPage;
